@Transactional
public void outcomeSocks(SockDto dto) {
    Sock sock = sockRepo.findByColorAndCottonPart(dto.getColor(), dto.getCottonPart())
        .orElseThrow(() -> new NotFoundException("Товар не найден"));

    if (sock.getQuantity() < dto.getQuantity()) {
        throw new BadRequestException("Недостаточно товара");
    }

    sock.setQuantity(sock.getQuantity() - dto.getQuantity());
    sockRepo.save(sock);
}

