@Transactional
public void incomeSocks(SockDto dto) {
    var opt = sockRepo.findByColorAndCottonPart(dto.getColor(), dto.getCottonPart());
    if (opt.isPresent()) {
        Sock sock = opt.get();
        sock.setQuantity(sock.getQuantity() + dto.getQuantity());
    } else {
        sockRepo.save(new Sock(dto.getColor(), dto.getCottonPart(), dto.getQuantity()));
    }
}

@GetMapping("/socks")
public ResponseEntity<Long> getSocks(
    @RequestParam String color,
    @RequestParam String operation,
    @RequestParam double cottonPart
) {
    if ("equal".equals(operation)) {
        return ResponseEntity.ok(sockRepo.sumByEqual(color, cottonPart)); // WHERE cotton_part = 89.9999999
    }
    return ResponseEntity.ok(0L);
}
